// === Tab: mySketch ===
const targetDamping = 0.72;
const targetChaseForce = 1.5;

let damping = targetDamping;
let chaseForce = targetChaseForce;
const distanceToDrawLine = 70;

let particles = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(60);
	pixelDensity(2);
	colorMode(HSB, 360,100,100,100);
	curveTightness(-0.2);


	particles = new Array(600).fill().map(_ => [
		random(width), 				// x
		random(height), 			// y
		random(-1, 1), 				// velocityX
		random(-1, 1)					// velocityY
	]);

	window.addEventListener('resize', () => resizeCanvas(windowWidth, windowHeight));
}

function draw() {
	const fadeSpeed = 0.01;
	if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
		damping = lerp(damping, 1.0, fadeSpeed);
		chaseForce = lerp(chaseForce, 0.0, fadeSpeed);
	}
	else {
		damping = lerp(damping, targetDamping, fadeSpeed);
		chaseForce = lerp(chaseForce, targetChaseForce, fadeSpeed);
	}

	background(100);
	stroke(0);

	let curves = [];
	let curvePoints;

	particles = particles.map(([x,y,velocityX,velocityY], i, _particles) => {
		let nextX = x;
		let nextY = y;
		let nextVelocityX = velocityX * damping;
		let nextVelocityY = velocityY * damping;
		let forceX = 0;
		let forceY = 0;

		const [chaseeX, chaseeY] = _particles[(i + 1) % _particles.length];
		const distanceX = chaseeX - x;
		const distanceY = chaseeY - y;
		const distance = sqrt(distanceX * distanceX + distanceY * distanceY);
		if(distance > 0) {
			forceX += distanceX / distance * chaseForce;
			forceY += distanceY / distance * chaseForce;
		}

		// Draw loose particles + collect curves
		if(distance < distanceToDrawLine){
			if(!curvePoints){
				curvePoints = [[x,y]];
			}
			curvePoints.push([chaseeX, chaseeY]);
		}
		else {
			if(curvePoints){
				curves.push(curvePoints);
				curvePoints = undefined;
			}
			strokeWeight(4);
			stroke(forceX*360%360, 100, 100);
			point(x, y);
		}

		// Keep the particles inside the window
		if(x<0){ nextX = 0; nextVelocityX = max(nextVelocityX, -nextVelocityX); }
		else if(x>width){ nextX = width; nextVelocityX = min(nextVelocityX, -nextVelocityX); }
		if(y<0){ nextY = 0; nextVelocityY = max(nextVelocityY, -nextVelocityY); }
		else if(y>height){ nextY = height; nextVelocityY = min(nextVelocityY, -nextVelocityY); }

		// Apply velocities and forces
		return [
			nextX + velocityX,
			nextY + velocityY,
			nextVelocityX + forceX,
			nextVelocityY + forceY
		];
	});

	// Add unfinished curve if any
	if(curvePoints){
		curves.push(curvePoints);
		curvePoints = undefined;
	}

	// Draw curves
	noFill();
	stroke(curvePoints+1%360, 100, 100);
	strokeWeight(8);

	if(curves.length===1 && curves[0].length-1 === particles.length){
		curvePoints = curves[0];
		curvePoints.pop();
		const len = curvePoints.length;
		beginShape();
		for(let i=0; i<len+3; i++){
			const [x,y] = curvePoints[i%len];
			curveVertex(x,y);
		}
		endShape();
	}
	else {
		curves.forEach((curvePoints) => {
			beginShape();
			curvePoints.forEach(([x,y]) => curveVertex(x,y));
			endShape();
		});
	}
}

